import { join } from 'node:path'

const definitionsDir = join(import.meta.dir, '..', 'src', 'services', 'definitions')
const manifestPath = join(definitionsDir, 'index.ts')

const files = [...new Bun.Glob('*.ts').scanSync(definitionsDir)]
    .filter((file) => file !== 'index.ts')
    .sort()

const lines = [
    '// AUTO-GENERATED by scripts/generate-service-manifest.ts — do not edit by hand.',
    '// Regenerated automatically by `bun run dev` / `bun run build` (or manually: `bun run generate:services`).',
    '',
    ...files.map((file) => `import './${file.replace(/\.ts$/, '')}'`),
]

await Bun.write(manifestPath, lines.join('\n') + '\n')

console.log(`Generated services/definitions/index.ts with ${files.length} definition${files.length === 1 ? '' : 's'}.`)